CREATE TABLE IF NOT EXISTS fee_obligations (id VARCHAR(64) PRIMARY KEY, school_id VARCHAR(64) NOT NULL, fee_structure_id VARCHAR(64) NOT NULL, academic_year_id VARCHAR(64), term_id VARCHAR(64), applicability_type VARCHAR(32) NOT NULL, class_id VARCHAR(64), student_id VARCHAR(64) NOT NULL, amount_minor BIGINT NOT NULL, due_date DATE, status VARCHAR(32) NOT NULL, published_by VARCHAR(64) NOT NULL, published_at DATETIME NOT NULL, idempotency_key VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY uq_fee_obligation_scope (school_id, idempotency_key), KEY idx_fee_obligations_student (school_id, student_id));
CREATE TABLE IF NOT EXISTS fee_collection_records (id VARCHAR(64) PRIMARY KEY, school_id VARCHAR(64) NOT NULL, collection_type VARCHAR(32) NOT NULL, class_id VARCHAR(64), collection_date DATE NOT NULL, expected_amount_minor BIGINT, amount_received_minor BIGINT NOT NULL, recorded_by VARCHAR(64) NOT NULL, notes TEXT, academic_year_id VARCHAR(64), term_id VARCHAR(64), created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, KEY idx_fee_collections_period (school_id, collection_type, collection_date));
